#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/linker/sections.h>

struct test_struct {
	int val;
	int val2;
};

struct another_struct {
	long val;
};

/* ROM section elements */
#define ROM_VAL1 1
#define ROM_VAL2 3
#define ROM_VAL3 5
#define ROM_VAL4 7
#define ROM_ALT_VAL1 101
#define ROM_ALT_VAL2 103

STRUCT_SECTION_DEFINE(test_struct, test_rom_1, = { .val = ROM_VAL1 });
STRUCT_SECTION_DEFINE(test_struct, test_rom_2, = { .val = ROM_VAL2 });
STRUCT_SECTION_DEFINE_NAMED(test_struct, test_rom_3, = { .val = ROM_VAL3 });
STRUCT_SECTION_DEFINE_NAMED(test_struct, test_rom_4, = { .val = ROM_VAL4 });
STRUCT_SECTION_DEFINE_ALTERNATE(test_struct, test_rom_alt_1, = { .val = ROM_ALT_VAL1 });
STRUCT_SECTION_DEFINE_NAMED_ALTERNATE(test_struct, test_rom_alt_2, = { .val = ROM_ALT_VAL2 });

#define ROM_EXPECT (ROM_VAL1 + ROM_VAL2 + ROM_VAL3 + ROM_VAL4)
#define ROM_ALT_EXPECT (ROM_ALT_VAL1 + ROM_ALT_VAL2)

/* RAM section elements */
#define RAM_VAL1 11
#define RAM_VAL2 13
#define RAM_VAL3 15
#define RAM_VAL4 17
#define RAM_ALT_VAL1 111
#define RAM_ALT_VAL2 113

STRUCT_SECTION_DEFINE(test_struct, test_ram_1) = { .val = RAM_VAL1 };
STRUCT_SECTION_DEFINE(test_struct, test_ram_2) = { .val = RAM_VAL2 };
STRUCT_SECTION_DEFINE_NAMED(test_struct, test_ram_3) = { .val = RAM_VAL3 };
STRUCT_SECTION_DEFINE_NAMED(test_struct, test_ram_4) = { .val = RAM_VAL4 };
STRUCT_SECTION_DEFINE_ALTERNATE(test_struct, test_ram_alt_1) = { .val = RAM_ALT_VAL1 };
STRUCT_SECTION_DEFINE_NAMED_ALTERNATE(test_struct, test_ram_alt_2) = { .val = RAM_ALT_VAL2 };

#define RAM_EXPECT (RAM_VAL1 + RAM_VAL2 + RAM_VAL3 + RAM_VAL4)
#define RAM_ALT_EXPECT (RAM_ALT_VAL1 + RAM_ALT_VAL2)

static void *iterable_sections_setup(void)
{
	/* Mutate RAM values to ensure we're not just getting the
	 * initializer content.
	 */
	struct test_struct *s;

	STRUCT_SECTION_FOREACH(test_struct, s) {
		s->val += 1;
	}
	STRUCT_SECTION_FOREACH_ALTERNATE(test_struct, s) {
		s->val += 1;
	}

	return NULL;
}

static void iterable_sections_teardown(void)
{
	/* Revert mutation of RAM values to leave it as the
	 * initializer content.
	 */
	struct test_struct *s;

	STRUCT_SECTION_FOREACH(test_struct, s) {
		s->val -= 1;
	}
	STRUCT_SECTION_FOREACH_ALTERNATE(test_struct, s) {
		s->val -= 1;
	}
}

ZTEST_SUITE(iterable_sections, NULL, iterable_sections_setup, NULL, NULL,
	    iterable_sections_teardown);

ZTEST(iterable_sections, test_ram)
{
	int out = 0;
	struct test_struct *s;

	/* test the iterator */
	STRUCT_SECTION_FOREACH(test_struct, s) {
		out += s->val;
	}

	zassert_equal(out, RAM_EXPECT + STRUCT_SECTION_COUNT(test_struct),
		      "iterable_sections_test_ram failed");

	/* test the by-index accessors */
	out = 0;
	for (size_t i = 0; i < STRUCT_SECTION_COUNT(test_struct); i++) {
		s = STRUCT_SECTION_GET(test_struct, i);
		out += s->val;
	}

	zassert_equal(out, RAM_EXPECT + STRUCT_SECTION_COUNT(test_struct),
		      "iterable_sections_test_ram by-index failed");

	/* Test alternate section */
	out = 0;
	STRUCT_SECTION_FOREACH_ALTERNATE(test_struct, s) {
		out += s->val;
	}

	zassert_equal(out, RAM_ALT_EXPECT + STRUCT_SECTION_COUNT_ALTERNATE(test_struct),
		      "iterable_sections_test_ram_alt failed");

	out = 0;
	for (size_t i = 0; i < STRUCT_SECTION_COUNT_ALTERNATE(test_struct); i++) {
		s = STRUCT_SECTION_GET_ALTERNATE(test_struct, i);
		out += s->val;
	}

	zassert_equal(out, RAM_ALT_EXPECT + STRUCT_SECTION_COUNT_ALTERNATE(test_struct),
		      "iterable_sections_test_ram_alt by-index failed");
}

ZTEST(iterable_sections, test_rom)
{
	int out = 0;
	const struct test_struct *s;

	/* test the iterator */
	STRUCT_SECTION_FOREACH(test_struct, s) {
		out += s->val;
	}

	zassert_equal(out, ROM_EXPECT, "iterable_sections_test_rom failed");

	/* test the by-index accessors */
	out = 0;
	for (size_t i = 0; i < STRUCT_SECTION_COUNT(test_struct); i++) {
		s = STRUCT_SECTION_GET(test_struct, i);
		out += s->val;
	}

	zassert_equal(out, ROM_EXPECT, "iterable_sections_test_rom by-index failed");

	/* Test alternate section */
	out = 0;
	STRUCT_SECTION_FOREACH_ALTERNATE(test_struct, s) {
		out += s->val;
	}

	zassert_equal(out, ROM_ALT_EXPECT, "iterable_sections_test_rom_alt failed");

	out = 0;
	for (size_t i = 0; i < STRUCT_SECTION_COUNT_ALTERNATE(test_struct); i++) {
		s = STRUCT_SECTION_GET_ALTERNATE(test_struct, i);
		out += s->val;
	}

	zassert_equal(out, ROM_ALT_EXPECT, "iterable_sections_test_rom_alt by-index failed");
}

ZTEST(iterable_sections, test_empty)
{
	const struct another_struct *s;
	size_t count = 0;

	zassert_equal(STRUCT_SECTION_COUNT(another_struct), 0,
		      "another_struct count not zero");

	STRUCT_SECTION_FOREACH(another_struct, s) {
		count++;
	}
	zassert_equal(count, 0, "another_struct foreach not empty");
}
